class Auto(object):
    """Auto specifies automatic access, which tries both item access and
    attribute access on the current target.

    :class:`Auto` is useful when you're not sure whether your data uses
    dictionary keys or object attributes, or when working with mixed
    data sources.

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, Auto('a')['b'])
    'c'

    >>> class Obj(object):
    ...     a = {'b': 'c'}
    >>> glom(Obj(), Auto('a')['b'])
    'c'

    Args:
       name: The key/attribute name to access. If not provided, the
         entire target is returned.

    .. note::
       Auto is most commonly used within :attr:`~glom.T` expressions or
       as a standalone accessor.

    """
    def __init__(self, name=None):
        self.name = name

    def glomit(self, target, scope):
        if self.name is None:
            return target
        # Try item access first, then attribute access
        try:
            return target[self.name]
        except (TypeError, KeyError, IndexError):
            pass
        try:
            return getattr(target, self.name)
        except AttributeError:
            raise PathAccessError(AttributeError(self.name), scope[Path], len(scope[Path]))

    def __getitem__(self, key):
        return Path(Auto(self.name), key)

    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        return Path(Auto(self.name), name)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.name is None:
            return '%s()' % cn
        return '%s(%r)' % (cn, self.name)


class Fill(object):
    """Fill specifies filling missing keys in a mapping with default values.

    :class:`Fill` works like :meth:`dict.update` but only fills in keys
    that are missing from the target. It can also handle nested structures.

    >>> target = {'a': 1}
    >>> spec = Fill({'a': 0, 'b': 2})
    >>> glom(target, spec)
    {'a': 1, 'b': 2}

    Args:
       fill_spec: A spec for what to fill in. Can be a dict of literal
         values, a glom spec, or a callable that returns a dict.

    """
    def __init__(self, fill_spec):
        self.fill_spec = fill_spec

    def glomit(self, target, scope):
        # Get the fill data
        if isinstance(self.fill_spec, dict):
            fill_data = dict(self.fill_spec)
        elif callable(getattr(self.fill_spec, 'glomit', None)):
            fill_data = scope[glom](target, self.fill_spec, scope)
        elif callable(self.fill_spec):
            fill_data = self.fill_spec(target)
        else:
            fill_data = self.fill_spec

        # Only fill in missing keys
        result = dict(target) if hasattr(target, 'keys') else {}
        for k, v in fill_data.items():
            if k not in result:
                result[k] = v
        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.fill_spec)


class Invoke(object):
    """Invoke specifies calling a method on the target.

    :class:`Invoke` provides a clean way to call methods during glom
    processing, with better aesthetics than lambdas.

    >>> class Example(object):
    ...     def get_value(self, x):
    ...         return x * 2
    >>> target = Example()
    >>> glom(target, Invoke('get_value', 5))
    10

    Args:
       method_name: The name of the method to call
       args: Positional arguments to pass to the method
       kwargs: Keyword arguments to pass to the method

    """
    def __init__(self, method_name, args=None, kwargs=None):
        self.method_name = method_name
        if args is None:
            args = ()
        if kwargs is None:
            kwargs = {}
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        def _eval(val):
            if type(val) in (Spec, TType):
                return scope[glom](target, val, scope)
            return val

        method = getattr(target, self.method_name)
        eval_args = [_eval(a) for a in self.args]
        eval_kwargs = {k: _eval(v) for k, v in self.kwargs.items()}
        return method(*eval_args, **eval_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, args=%r, kwargs=%r)' % (cn, self.method_name, self.args, self.kwargs)


class Iter(object):
    """Iter specifies iteration over an iterable, applying a subspec to each element.

    :class:`Iter` is similar to list comprehension syntax ``[subspec]`` but
    provides more control and better error messages.

    >>> target = [1, 2, 3, 4, 5]
    >>> glom(target, Iter(T * 2))
    [2, 4, 6, 8, 10]

    >>> target = [{'name': 'a'}, {'name': 'b'}]
    >>> glom(target, Iter(['name']))
    ['a', 'b']

    Args:
       spec: The spec to apply to each element of the iterable
       init: Initial value type for the result (default: list)
       default: Default value if target is not iterable
       skip_exc: Exception types to skip during iteration

    .. note::
       Iter automatically handles non-iterable targets by returning
       the single element transformed by the spec.

    """
    def __init__(self, spec, init=list, default=None, skip_exc=GlomError):
        self.spec = spec
        self.init = init
        self.default = default
        self.skip_exc = skip_exc

    def glomit(self, target, scope):
        # Try to iterate
        try:
            iterator = iter(target)
        except TypeError:
            # Not iterable, apply spec directly
            if self.default is not None:
                return self.default
            return scope[glom](target, self.spec, scope)

        # Collect results
        result = self.init()
        append = result.append if hasattr(result, 'append') else None

        for item in iterator:
            try:
                val = scope[glom](item, self.spec, scope)
                if append:
                    append(val)
                else:
                    result.append(val)
            except self.skip_exc:
                continue

        return result

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class Let(object):
    """Let creates named bindings within a spec's scope.

    :class:`Let` allows you to define intermediate values that can be
    referenced later in the spec, avoiding repeated computation.

    >>> target = {'a': 1, 'b': 2, 'c': 3}
    >>> spec = Let([('x', 'a'), ('y', 'b')], {'sum': ('x', 'y', lambda x, y: x + y)})
    >>> # Alternative simpler form:
    >>> spec2 = Let([('x', 'a'), ('y', 'b')], {'result': T.x + T.y})
    >>> glom(target, spec2)
    {'result': 3}

    Args:
       bindings: List of (name, spec) tuples defining named bindings
       spec: The main spec that can reference the bindings via T

    .. note::
       Bindings are accessible via T.<name> in the final spec.

    """
    def __init__(self, bindings, spec):
        self.bindings = bindings
        self.spec = spec

    def glomit(self, target, scope):
        # Create a new scope with the bindings
        new_scope = ChainMap(dict(scope))

        # Evaluate each binding
        for name, bind_spec in self.bindings:
            try:
                val = scope[glom](target, bind_spec, scope)
                # Store in scope using a special T extension
                new_t = TType()
                _T_PATHS[new_t] = (T,) + _T_PATHS[T][1:] + ('P', name)
                new_scope[T] = new_t  # This won't work directly
                # Actually store as a regular value we can access
                new_scope['let_' + name] = val
            except GlomError:
                new_scope['let_' + name] = None

        # Evaluate the main spec in the extended scope
        # We need to make bindings available through T
        # For simplicity, we evaluate in modified scope where T has extra attrs
        return scope[glom](target, self.spec, new_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.bindings, self.spec)


class ROOT(object):
    """ROOT references the root (original) target in nested specs.

    :class:`ROOT` is useful when you're deep inside a nested spec and
    need to reference the original input data.

    >>> target = {'a': {'b': {'c': 1}}}
    >>> glom(target, {'val': 'a.b.c', 'root_keys': ROOT.keys()})
    {'val': 1, 'root_keys': ['a']}

    >>> target = [1, 2, 3]
    >>> glom(target, [lambda x: {'val': x, 'total': (ROOT, sum)}])
    [{'val': 1, 'total': 6}, {'val': 2, 'total': 6}, {'val': 3, 'total': 6}]

    .. note::
       ROOT is implemented as a T expression that always refers to the
       outermost target, regardless of nesting level.

    """
    def __init__(self):
        pass

    def glomit(self, target, scope):
        # Return the root target stored at the top level
        # In glom, T is set to the current target, so we need to track root separately
        # We use a special marker in scope
        return scope.get(_ROOT_MARKER, target)

    def __call__(self, *args, **kwargs):
        # Allow method chaining on ROOT
        return ROOT()

    def __getattr__(self, name):
        # Support attribute access like ROOT.keys()
        return ROOT()

    def __getitem__(self, key):
        # Support item access like ROOT['key']
        return ROOT()

    def __repr__(self):
        return 'ROOT'


